example.code:
User source = new()
{
    Id = 1,
    Email = "joe@mail.com",
    Name = new()
    {
        GivenName = "Joe",
    },
};

User target = new()
{
    Id = 1,
    Email = "joe@mail.com",
    Name = new()
    {
        GivenName = "Joe",
    },
};

Assert.True(source.IsEquivalentOf(target));
Assert.True(target.IsEquivalentOf(source));

member.summary:
Checks if the source value is null or an equivalent of a target value;
or if every element of a source array, list or dictionary is a subset of the corresponding target array, list or dictionary,
or if every property and field of a source object is a subset of the corresponding property or field of the target object.

example.code:
User source = new()
{
    Id = 1,
    Email = "joe@mail.com",
    Name = new()
    {
        GivenName = "Joe"
    }
};

User target1 = new()
{
    Id = 1,
    Email = "joe@mail.com"
};

User target2 = new()
{
    Id = 2,
    Email = "joe@mail.com",
    Name = new()
    {
        GivenName = "Joe",
    },
};

Assert.True(source.IsPartialEquivalentOf(target1));
Assert.False(target1.IsPartialEquivalentOf(source));
Assert.False(source.IsPartialEquivalentOf(target2));

member.summary:
Checks if the source value is null or an equivalent of a target value;
or if every element of a source array, list or dictionary is a subset of the corresponding target array, list or dictionary,
or if every property and field of a source object is a subset of the corresponding property or field of the target object.

example.code:
User source = new()
{
    Id = 1,
    Email = "joe@mail.com",
    Name = new()
    {
        GivenName = "Joe"
    }
};

User target1 = new()
{
    Id = 1,
    Email = "joe@mail.com"
};

User target2 = new()
{
    Id = 2,
    Email = "joe@mail.com",
    Name = new()
    {
        GivenName = "Joe",
    },
};

Assert.True(source.IsPartialEquivalentOf(target1));
Assert.False(target1.IsPartialEquivalentOf(source));
Assert.False(source.IsPartialEquivalentOf(target2));

